<script setup lang="ts">import {ref,onMounted} from 'vue';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createRun} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RunTable from '../components/RunTable.vue';import {features} from '../constants/enums';const store=useResearch(),auth=useAuth(),name=ref('冬季复学 · 四维分群'),dataset=ref(0),selected=ref(Object.keys(features)),kmin=ref(2),kmax=ref(6),mustText=ref(''),cannotText=ref(''),sizeMin=ref(''),sizeMax=ref(''),message=ref(''),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await store.load();dataset.value=store.datasets[0]?.id||0;}));usePolling(async()=>{if(store.runs.some(r=>['queued','running'].includes(r.status)))await store.load();});
function parsePairs(text:string,label:string):string[][]{const pairs:string[][]=[],seen=new Set<string>();text.split('\n').map(l=>l.trim()).filter(Boolean).forEach((line,i)=>{const parts=line.split(/[\s,，、;；]+/).filter(Boolean);if(parts.length!==2)throw new Error(`${label}第 ${i+1} 行需为两个匿名编号，以空格或逗号分隔`);const[a,b]=parts;if(a===b)throw new Error(`${label}第 ${i+1} 行：编号 ${a} 不能与自身配对`);const key=[a,b].sort().join('|');if(!seen.has(key)){seen.add(key);pairs.push([a,b]);}});return pairs;}
function parseSize(raw:string,label:string):number|null{if(raw==='')return null;const n=Number(raw);if(!Number.isInteger(n)||n<1)throw new Error(`${label}需为不小于 1 的整数`);return n;}
function submit(){perform(async()=>{const must=parsePairs(mustText.value,'同群约定'),cannot=parsePairs(cannotText.value,'异群约定');const cannotKeys=new Set(cannot.map(p=>[...p].sort().join('|')));const both=must.find(p=>cannotKeys.has([...p].sort().join('|')));if(both)throw new Error(`关系冲突：${both[0]} 与 ${both[1]} 既约定同群又约定异群`);const min=parseSize(sizeMin.value,'每群最少人数'),max=parseSize(sizeMax.value,'每群最多人数');if(min!==null&&max!==null&&min>max)throw new Error('每群人数下限不能大于上限');const constraints=(must.length||cannot.length||min!==null||max!==null)?{must_link:must,cannot_link:cannot,size_min:min,size_max:max}:undefined;const run=await createRun({name:name.value,dataset_id:dataset.value,features:selected.value,k_min:kmin.value,k_max:kmax.value,...(constraints?{constraints}:{})});message.value=`研究 #${run.id} 已进入计算队列。完成后从下方查看群组解释。`;await store.load();});}</script><template><PageHeading eyebrow="EXPERIMENT / FEATURE & MODEL CHOICE" title="让分群选择有据可查" description="标准化每个特征，比较候选 K 的轮廓系数。每次研究保留独立结果。"/><ErrorNotice :message="error" @retry="perform(store.load)"/><div class="experiment-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><p class="eyebrow">NEW FIELD STUDY</p><h2>建立分群实验</h2><label>研究名称<input v-model="name" required minlength="2" maxlength="160"></label><label>观察数据集<select v-model="dataset"><option v-for="d in store.datasets" :value="d.id" :key="d.id">{{d.name}}</option></select></label><fieldset><legend>研究特征 <small>至少选择 2 项</small></legend><label v-for="(label,key) in features" :key="key" class="checkbox"><input v-model="selected" type="checkbox" :value="key">{{label}}</label></fieldset><div class="form-row"><label>K 下限<select v-model="kmin"><option v-for="k in [2,3,4,5,6]" :value="k">{{k}}</option></select></label><label>K 上限<select v-model="kmax"><option v-for="k in [2,3,4,5,6]" :value="k">{{k}}</option></select></label></div><fieldset><legend>分群约束 <small>可选 · 按匿名编号约定</small></legend><label>同群约定 <small>每行一对编号；关系可传递，同户客户不再被拆散</small><textarea v-model="mustText" rows="3" placeholder="WA-0001 WA-0002"></textarea></label><label>异群约定 <small>每行一对编号，二者必须分入不同群</small><textarea v-model="cannotText" rows="3" placeholder="WA-0003 WA-0009"></textarea></label><div class="form-row"><label>每群最少人数<input v-model="sizeMin" type="number" min="1" max="5000" placeholder="不限"></label><label>每群最多人数<input v-model="sizeMax" type="number" min="1" max="5000" placeholder="不限"></label></div></fieldset><button class="primary" :disabled="busy||selected.length<2||kmin>kmax">{{busy?'正在提交…':'提交到计算队列 →'}}</button><p v-if="message" class="success" role="status">{{message}}</p></form><section v-else class="research-form"><h2>当前为阅读权限</h2><p>你可以查看研究与下载已批准的匿名名单；新建研究需要研究员或负责人账号。</p></section><aside class="method-note"><span class="note-number">01 / METHOD</span><h2>先统一尺度，<br>再讨论距离。</h2><ol><li><b>Z-score 标准化</b><p>每一列减均值、除以标准差，避免金额量纲压过学习频次。</p></li><li><b>比较 K = 2…6</b><p>每个候选使用 KMeans，seed=42，10 次初始化。</p></li><li><b>以轮廓系数选优</b><p>s=(b−a)/max(a,b)，越接近 1 分离越清晰；同分选更小的 K。</p></li><li><b>约束先行</b><p>录入同群、异群或人数约定时，每个候选 K 先回溯寻找满足全部约束的分群，再比较轮廓系数；无解会说明冲突或人数依据。</p></li></ol><small>分群是观察工具，业务标签来自中心特征规则，不代表因果结论。</small></aside></div><section class="recent"><div class="section-title"><h2>所有研究 <small>队列状态自动刷新</small></h2></div><RunTable :runs="store.runs"/></section></template>
